def chain_follow(chain):
    chain = list(chain)
    chain.sort(key=lambda x: (-len(x), x))
    result = []
    for i in range(len(chain)):
        if i == 0:
            result.append(chain[i])
        else:
            if chain[i-1][-1] != chain[i][0]:
                raise ValueError("Invalid chain")
            result.append(chain[i][0])
    return result

# Example usage:
# print(chain_follow(['bbb', 'ccc']))  # Should print ['bbb', 'ccc']
